4193	Status SegmentImpl::recover() {
4194	  // recover mem block meta
4195	  auto &mem_block = segment_meta_->writing_forward_block().value();
4196	  doc_id_allocator_.store(mem_block.min_doc_id());
4197	
4198	  std::string wal_file_path =
4199	      FileHelper::MakeWalPath(path_, segment_meta_->id(), mem_block.id_);
4200	  if (!std::filesystem::exists(wal_file_path)) {
4201	    LOG_INFO("WAL recovery skipped: no WAL file exists [%s]",
4202	             wal_file_path.c_str());
4203	    return Status::OK();
4204	  }
4205	
4206	  WalFilePtr recover_wal_file;
4207	  WalOptions wal_option;
4208	  wal_option.create_new = false;
4209	  if (WalFile::CreateAndOpen(wal_file_path, wal_option, &recover_wal_file) !=
4210	      0) {
4211	    LOG_ERROR("WAL recovery failed: unable to open WAL file [%s]",
4212	              wal_file_path.c_str());
4213	    return Status::OK();
4214	  }
4215	  AILEGO_DEFER([&]() { recover_wal_file->close(); });
4216	
4217	  std::array<uint64_t, static_cast<size_t>(Operator::DELETE) + 1>
4218	      recovered_doc_count{};
4219	  uint64_t total_recovered_doc_count{0};
4220	
4221	  int ret = recover_wal_file->prepare_for_read();
4222	  if (ret != 0) {
4223	    LOG_ERROR(
4224	        "WAL recovery failed: unable to prepare WAL file [%s] for reading",
4225	        wal_file_path.c_str());
4226	    return Status::InternalError("Failed to prepare wal file: ", wal_file_path,
4227	                                 " for read");
4228	  }
4229	
4230	  LOG_INFO("WAL recovery started [%s]", wal_file_path.c_str());
4231	
4232	  std::lock_guard<std::mutex> lock(seg_mtx_);
4233	
4234	  while (true) {
4235	    std::string buf = recover_wal_file->next();
4236	    if (buf.empty()) {
4237	      LOG_INFO("WAL recovery completed [%s]", wal_file_path.c_str());
4238	      break;
4239	    }
4240	    total_recovered_doc_count++;
4241	    auto doc = Doc::deserialize(reinterpret_cast<const uint8_t *>(buf.data()),
4242	                                buf.size());
4243	    if (doc == nullptr) {
4244	      LOG_ERROR("WAL recovery failed [%s]: doc deserialization error at %zu",
4245	                wal_file_path.c_str(), (size_t)total_recovered_doc_count);
4246	      continue;
4247	    }
4248	
4249	    Status status;
4250	    switch (doc->get_operator()) {
4251	      case Operator::INSERT: {
4252	        internal_insert(*doc);
4253	        break;
4254	      }
4255	      case Operator::UPDATE: {
4256	        internal_update(*doc);
4257	        break;
4258	      }
4259	      case Operator::UPSERT: {
4260	        internal_upsert(*doc);
4261	        break;
4262	      }
4263	      case Operator::DELETE: {
4264	        internal_delete(*doc);
4265	        break;
4266	      }
4267	      default:
4268	        LOG_ERROR("WAL recovery failed [%s]: unknown operator type %d at %zu ",
4269	                  wal_file_path.c_str(), static_cast<int>(doc->get_operator()),
4270	                  (size_t)total_recovered_doc_count);
4271	        break;
4272	    }
4273	
4274	    if (!status.ok()) {
4275	      LOG_ERROR(
4276	          "WAL recovery failed [%s]: operation %d failed at %zu, reason: %s",
4277	          wal_file_path.c_str(), static_cast<int>(doc->get_operator()),
4278	          (size_t)total_recovered_doc_count, status.message().c_str());
4279	      continue;
4280	    }
4281	
4282	    recovered_doc_count[static_cast<size_t>(doc->get_operator())]++;
4283	  }
4284	
4285	  const auto added_docs = recovered_doc_count[0] +  // INSERT
4286	                          recovered_doc_count[1] +  // UPSERT
4287	                          recovered_doc_count[2];   // UPDATE
4288	  mem_block.max_doc_id_ += added_docs;
4289	
4290	  LOG_INFO(
4291	      "WAL recovery completed [%s]: segment[%d], total_recovered[%zu] "
4292	      "(insert[%zu], upsert[%zu], update[%zu], delete[%zu])",
4293	      wal_file_path.c_str(), id(), (size_t)total_recovered_doc_count,
4294	      (size_t)recovered_doc_count[0],  // INSERT
4295	      (size_t)recovered_doc_count[1],  // UPSERT
4296	      (size_t)recovered_doc_count[2],  // UPDATE
4297	      (size_t)recovered_doc_count[3]   // DELETE
4298	  );
4299	
4300	  return Status::OK();
4301	}
