4342	Status SegmentImpl::finish_memory_components() {
4343	  auto block = segment_meta_->writing_forward_block().value();
4344	
4345	  // close for loading persist block
4346	  auto s = memory_store_->close();
4347	  CHECK_RETURN_STATUS(s);
4348	  memory_store_.reset();
4349	
4350	  // load forward store
4351	  auto persist_forward_store_path = FileHelper::MakeForwardBlockPath(
4352	      path_, segment_meta_->id(), block.id_, !options_.enable_mmap_);
4353	
4354	  BaseForwardStore::Ptr persist_store;
4355	  if (options_.enable_mmap_) {
4356	    persist_store =
4357	        std::make_shared<MmapForwardStore>(persist_forward_store_path);
4358	  } else {
4359	    persist_store =
4360	        std::make_shared<BufferPoolForwardStore>(persist_forward_store_path);
4361	  }
4362	  s = persist_store->Open();
4363	  CHECK_RETURN_STATUS(s);
4364	  persist_stores_.push_back(persist_store);
4365	
4366	  BlockMeta b{block.id_,         block.type_,      block.min_doc_id_,
4367	              block.max_doc_id_, block.doc_count_, block.columns_};
4368	  segment_meta_->add_persisted_block(b);
4369	
4370	  // remove indexer from memory to persist
4371	  for (auto &[column_name, indexer] : memory_vector_indexers_) {
4372	    auto block_id = memory_vector_block_ids_[column_name];
4373	    BlockMeta vb =
4374	        BlockMeta{block_id,          BlockType::VECTOR_INDEX, block.min_doc_id_,
4375	                  block.max_doc_id_, block.doc_count_,        {column_name}};
4376	    auto it = vector_indexers_.find(column_name);
4377	    if (it == vector_indexers_.end()) {
4378	      std::vector<VectorColumnIndexer::Ptr> vector_indexers{indexer};
4379	      vector_indexers_.emplace(column_name, std::move(vector_indexers));
4380	    } else {
4381	      it->second.push_back(indexer);
4382	    }
4383	    segment_meta_->add_persisted_block(vb);
4384	  }
4385	
4386	  // remove quant indexer from memory to persist
4387	  for (auto &[column_name, indexer] : quant_memory_vector_indexers_) {
4388	    auto block_id = quant_memory_vector_block_ids_[column_name];
4389	    BlockMeta block_meta(block_id, BlockType::VECTOR_INDEX_QUANTIZE,
4390	                         block.min_doc_id_, block.max_doc_id_, block.doc_count_,
4391	                         {column_name});
4392	
4393	    auto it = quant_vector_indexers_.find(column_name);
4394	    if (it == quant_vector_indexers_.end()) {
4395	      std::vector<VectorColumnIndexer::Ptr> vector_indexers;
4396	      vector_indexers.push_back(indexer);
4397	      quant_vector_indexers_.emplace(column_name, std::move(vector_indexers));
4398	    } else {
4399	      it->second.push_back(indexer);
4400	    }
4401	    segment_meta_->add_persisted_block(block_meta);
4402	  }
4403	
4404	  // clear memory vector indexers
4405	  memory_vector_indexers_.clear();
4406	  quant_memory_vector_indexers_.clear();
4407	  memory_vector_block_ids_.clear();
4408	  quant_memory_vector_block_ids_.clear();
4409	
4410	  fresh_persist_block_offset();
4411	  return Status::OK();
4412	}
