4417	      version_manager_->set_delete_snapshot_path_suffix(
4418	          delete_snapshot_path_suffix);
4419	    }
4420	    auto s = version_manager_->reset_writing_segment_meta(segment_meta_);
4421	    CHECK_RETURN_STATUS(s);
4422	    s = version_manager_->flush();
4423	    CHECK_RETURN_STATUS(s);
4424	  }
4425	  return Status::OK();
